  ctx.fillStyle = "rgba(60,30,10,.18)"; ctx.fillRect(sx + 4, sy + 10, sw, 8);
  ctx.fillStyle = "#9a6538"; roundRect(sx, sy, sw, 10, 3); ctx.fill();
  const jars = [["#f4efe4", 0.36], ["#e8b04a", 0.3], ["#c9583a", 0.24], ["#f7f2e8", 0.33]];
  let jx = sx + 10;
